"""Frozen schema v1 for ordered migrations and regression fixtures."""
SCHEMA_V1 = "\nCREATE TABLE candidate_profiles (id TEXT PRIMARY KEY, payload TEXT NOT NULL);\nCREATE TABLE resumes (id TEXT PRIMARY KEY, payload TEXT NOT NULL,\n candidate_id TEXT NOT NULL REFERENCES candidate_profiles(id));\nCREATE TABLE approved_answers (id TEXT PRIMARY KEY, payload TEXT NOT NULL,\n candidate_id TEXT NOT NULL REFERENCES candidate_profiles(id), question TEXT NOT NULL,\n UNIQUE(candidate_id, question));\nCREATE TABLE job_criteria (id TEXT PRIMARY KEY, payload TEXT NOT NULL,\n candidate_id TEXT NOT NULL REFERENCES candidate_profiles(id));\nCREATE TABLE jobs (id TEXT PRIMARY KEY, payload TEXT NOT NULL,\n source TEXT NOT NULL, source_job_id TEXT NOT NULL, UNIQUE(source, source_job_id));\nCREATE TABLE applications (id TEXT PRIMARY KEY, payload TEXT NOT NULL,\n candidate_id TEXT NOT NULL REFERENCES candidate_profiles(id),\n job_id TEXT NOT NULL REFERENCES jobs(id), resume_id TEXT REFERENCES resumes(id),\n UNIQUE(candidate_id, job_id));\nCREATE TABLE contacts (id TEXT PRIMARY KEY, payload TEXT NOT NULL);\nCREATE TABLE outreach (id TEXT PRIMARY KEY, payload TEXT NOT NULL,\n candidate_id TEXT NOT NULL REFERENCES candidate_profiles(id),\n contact_id TEXT NOT NULL REFERENCES contacts(id),\n application_id TEXT REFERENCES applications(id));\nCREATE TABLE email_events (id TEXT PRIMARY KEY, payload TEXT NOT NULL,\n source TEXT NOT NULL, external_id TEXT NOT NULL,\n application_id TEXT REFERENCES applications(id), outreach_id TEXT REFERENCES outreach(id),\n UNIQUE(source, external_id));\nCREATE TABLE audit_logs (id TEXT PRIMARY KEY, payload TEXT NOT NULL);\nCREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_logs\n BEGIN SELECT RAISE(ABORT, 'Audit log is append-only'); END;\nCREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_logs\n BEGIN SELECT RAISE(ABORT, 'Audit log is append-only'); END;\n"
